<?php
declare(strict_types=1);
require dirname(__DIR__,2).'/app/bootstrap.php';
use AcePortal\\Auth;
$u=Auth::requireRoles(['customer']);
$q=db()->prepare('SELECT * FROM insureds WHERE id=:id');$q->execute(['id'=>$u['insured_id']]);$insured=$q->fetch();
$q=db()->prepare('SELECT policy_number,carrier_name,business_line,effective_date,expiration_date,total_premium,status FROM policies WHERE insured_id=:id ORDER BY id DESC');$q->execute(['id'=>$u['insured_id']]);$policies=$q->fetchAll();
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Customer Portal</title><link rel="stylesheet" href="/assets/app.css"></head><body><header class="topbar"><div><strong>ACE Insurance</strong><span>Customer Portal</span></div><div><?=e($u['full_name'])?> <a class="btn light small-btn" href="/logout.php">Logout</a></div></header><main class="customer-main"><div class="page-title"><div><h1>Welcome, <?=e($insured['legal_name']??$u['full_name'])?></h1><p class="muted">Your insurance account overview.</p></div></div><div class="panel"><h2>Insured Details</h2><div class="details-grid"><div><span>DOT Number</span><strong><?=e($insured['dot_number']??'')?></strong></div><div><span>Email</span><strong><?=e($insured['email']??'')?></strong></div><div><span>Phone</span><strong><?=e($insured['phone']??'')?></strong></div><div><span>Address</span><strong><?=e(implode(', ',array_filter([$insured['address_line1']??'',$insured['city']??'',$insured['state']??'',$insured['postal_code']??''])))?></strong></div></div></div><div class="panel"><h2>My Policies</h2><div class="table-wrap"><table><thead><tr><th>Policy #</th><th>Carrier</th><th>Business Line</th><th>Effective</th><th>Expiration</th><th>Premium</th><th>Status</th></tr></thead><tbody><?php foreach($policies as $p):?><tr><td><?=e($p['policy_number'])?></td><td><?=e($p['carrier_name']??'')?></td><td><?=e($p['business_line']??'')?></td><td><?=e($p['effective_date']??'')?></td><td><?=e($p['expiration_date']??'')?></td><td><?=e($p['total_premium']??'')?></td><td><?=e($p['status'])?></td></tr><?php endforeach;?><?php if(!$policies):?><tr><td colspan="7" class="muted">No policies available yet.</td></tr><?php endif;?></tbody></table></div></div></main></body></html>